 static int n,now;static UnitEntityData caster,other,owner;static EntityFactsManager facts;static readonly Dictionary<UnitDescriptor,HashSet<BlueprintGuid>> known=new Dictionary<UnitDescriptor,HashSet<BlueprintGuid>>();
 static T Empty<T>()where T:class=>(T)FormatterServices.GetUninitializedObject(typeof(T));static object Get(object o,string s)=>AccessTools.Field(o.GetType(),s).GetValue(o);static void Set(object o,string s,object v)=>AccessTools.Field(o.GetType(),s).SetValue(o,v);static void Check(bool b,string s){if(!b)throw new Exception("Spirit/Stasis: "+s);n++;}
 static T Asset<T>(BlueprintsCache c,string token)where T:SimpleBlueprint=>(T)c.Load((BlueprintGuid)AccessTools.Method(typeof(PsychicSpiritMagicBonus).Assembly.GetType("CallOfTheWild.Wrath.Prototype.PsychicAssets"),"Id").Invoke(null,new object[]{token}));
 static void Refresh()=>AccessTools.Method(Get(facts,"m_Cache").GetType(),"Clear").Invoke(Get(facts,"m_Cache"),null);static void Clear(){facts.List.Clear();Refresh();known.Clear();}
 static MechanicsContext Context(UnitEntityData u,BlueprintScriptableObject bp,int cl=12,Metamagic mm=0){var ctx=new MechanicsContext(u,owner.Descriptor,bp,null,new TargetWrapper(owner));ctx.SetParams(new AbilityParams {CasterLevel=cl,DC=23,SpellLevel=8,Metamagic=mm});var ranks=new int[32];foreach(var r in bp.GetComponents<ContextRankConfig>())ranks[(int)Get(r,"m_Type")]=r.GetValue(ctx);Set(ctx,"m_Ranks",ranks);return ctx;}
 static Buff Fact(BlueprintBuff bp,UnitEntityData u,string id){var f=Empty<Buff>();Set(f,"<Blueprint>k__BackingField",bp);Set(f,"<UniqueId>k__BackingField",id);Set(f,"Components",new List<EntityFactComponent>());Set(f,"m_Context",Context(u,bp));Set(f,"<Rank>k__BackingField",1);Set(f,"<IsActive>k__BackingField",true);Set(f,"<IsTurnedOn>k__BackingField",true);f.RestoreOwnerLink(facts);foreach(var comp in bp.ComponentsArray.Where(x=>x is PsychicSpiritMagicBonus||x is PsychicStasisPause)){var rt=(EntityFactComponent)AccessTools.Method(comp.GetType(),"CreateRuntimeFactComponent").Invoke(comp,null);rt.Setup(comp);rt.RestoreOwnerLink(f);Set(rt,"<IsTurnedOn>k__BackingField",true);f.Components.Add(rt);}facts.List.Add(f);Refresh();return f;}
 static void Grant(UnitEntityData u,BlueprintGuid id){known[u.Descriptor]=new HashSet<BlueprintGuid>{id};}
 internal static int Run(BlueprintsCache c){caster=new Psychic070Tests.Caster(c).Unit;other=new Psychic070Tests.Caster(c).Unit;owner=new Psychic070Tests.Caster(c).Unit;Set(caster,"Facts",new EntityFactsManager(caster));Set(other,"Facts",new EntityFactsManager(other));facts=new EntityFactsManager(owner);Set(owner,"Facts",facts);var bc=new BuffCollection();bc.Initialize(facts);Set(owner,"<Buffs>k__BackingField",bc);var h=new Harmony("CotW01324.SpiritTests");var old=Kingmaker.Game.Instance.TimeController;Set(Kingmaker.Game.Instance,"TimeController",Empty<Kingmaker.Controllers.TimeController>());h.Patch(AccessTools.PropertyGetter(typeof(Kingmaker.Controllers.TimeController),"GameTime"),prefix:new HarmonyMethod(typeof(PsychicSpiritTests),nameof(Time)));h.Patch(AccessTools.Method(typeof(UnitHelper),"HasFact",new[]{typeof(UnitDescriptor),typeof(Kingmaker.Blueprints.Facts.BlueprintFact)}),prefix:new HarmonyMethod(typeof(PsychicSpiritTests),nameof(HasFact)));
 try{Spirits(c);Domains(c);Stasis(c);}finally{h.UnpatchAll(h.Id);Set(Kingmaker.Game.Instance,"TimeController",old);Clear();}PsychicExpansionTests.Inventory["spiritSpellAssertions"]=n;Console.WriteLine("PASS: "+n+" spirit/stasis checks; native spell identities, current spirit filtering, nonstacking runtime ownership, duration, saved timer shifts and early cleanup; scene/time inputs seeded.");return n;}
 static bool Time(ref TimeSpan __result){__result=TimeSpan.FromSeconds(now);return false;}
