 static BlueprintAbility Unrelated(){var a=new BlueprintAbility {AssetGuid=BlueprintGuid.Parse("cccccccccccccccccccccccccccccccc"),ComponentsArray=Array.Empty<BlueprintComponent>()};Set(a,"m_Parent",new BlueprintAbilityReference());return a;}
 static int Bonus(object rule,string name){var b=(ModifiableBonus)Get(rule,name);return b==null?0:b.TotalValue;}
 static void Spirits(BlueprintsCache c){
 string[] tokens={"SenseSpiritMagic","SpiritCall","FontOfSpiritMagic"};
 for(int mode=0;mode<3;mode++){var a=Asset<BlueprintAbility>(c,tokens[mode]);var bp=Asset<BlueprintBuff>(c,tokens[mode]+"Effect");var comp=bp.GetComponent<PsychicSpiritMagicBonus>();Check(comp.Mode==mode&&comp.Spirits.Length==10,"Ten current native spirits mapped");Check(a.GetComponents<SpellListComponent>().All(x=>x.SpellLevel==(mode==2?3:1)),"Original class spell levels");var apply=(ContextActionApplyBuff)a.GetComponent<AbilityEffectRunAction>().Actions.Actions.Single();foreach(int cl in new[]{1,9,20})foreach(bool ext in new[]{false,true})Check(apply.DurationValue.Calculate(Context(caster,a,cl,ext?Metamagic.Extend:0)).Seconds==TimeSpan.FromSeconds((mode==0?86400:cl*(mode==1?60:6))*(ext?2:1)),"Native duration/Extend");if(mode>0){var area=Asset<BlueprintAbilityAreaEffect>(c,tokens[mode]+"Area");Check(area.Size.Value==(mode==1?60:30)&&area.GetComponent<AbilityAreaEffectBuff>().Buff==bp&&bp.Stacking==StackingType.Stack,"Owned separate overlap buffs and intended radius");}else Check(bp.Stacking==StackingType.Replace,"Sense refreshes");if(mode==2)Check(a.MaterialComponent.Count==1,"One diamond dust");
 foreach(var map in comp.Spirits){var refs=map.List.Get().SpellsByLevel.SelectMany(x=>(List<BlueprintAbilityReference>)Get(x,"m_Spells")).ToArray();Check(refs.Length>0,"Native list populated");foreach(bool wander in new[]{false,true}){if(wander&&map.Wandering==null)continue;Clear();Grant(caster,wander?map.Wandering.Guid:map.Primary.Guid);var foreign=Fact(bp,other,"foreign");var first=Fact(bp,caster,"first");var second=Fact(bp,caster,"second");var spell=new BlueprintAbility {AssetGuid=refs[0].Guid,name="ActualNativeIdentity",ComponentsArray=Array.Empty<BlueprintComponent>()};Set(spell,"m_Parent",new BlueprintAbilityReference());bool expected=!wander||mode!=1;
 var rt=first.Components.Single();using(rt.RequestEventContext()){Check((bool)AccessTools.Method(comp.GetType(),"Matches").Invoke(comp,new object[]{spell})==expected,"Primary/wandering rule uses caster's current facts");Check(!(bool)AccessTools.Method(comp.GetType(),"Matches").Invoke(comp,new object[]{Unrelated()}),"Unrelated spell rejected");}
 if(mode>0){var rule=new RuleCalculateAbilityParams(owner,spell,null);foreign.CallComponents<PsychicSpiritMagicBonus>(x=>x.OnEventAboutToTrigger(rule));first.CallComponents<PsychicSpiritMagicBonus>(x=>x.OnEventAboutToTrigger(rule));second.CallComponents<PsychicSpiritMagicBonus>(x=>x.OnEventAboutToTrigger(rule));Check(Bonus(rule,"m_BonusCasterLevel")== (expected&&mode==1?1:0)&&Bonus(rule,"m_BonusDC")== (expected&&mode==2?2:0)&&(int)Get(rule,"m_BonusConcentration")== (expected?(mode==1?4:2):0),"Overlapping copies contribute exactly once");Set(first,"<IsTurnedOn>k__BackingField",false);rule=new RuleCalculateAbilityParams(owner,spell,null);second.CallComponents<PsychicSpiritMagicBonus>(x=>x.OnEventAboutToTrigger(rule));Check((int)Get(rule,"m_BonusConcentration")== (expected?(mode==1?4:2):0),"Next active source takes over immediately");}
 else {var save=new RuleSavingThrow(owner,SavingThrowType.Will,23);save.Reason=new RuleReason(Context(other,spell));first.CallComponents<PsychicSpiritMagicBonus>(x=>x.OnEventAboutToTrigger(save));second.CallComponents<PsychicSpiritMagicBonus>(x=>x.OnEventAboutToTrigger(save));Check(save.AllBonuses.Sum(x=>x.Value)==2,"Sense grants one circumstance2 save modifier");}
 if(mode==2){var pen=new RuleSpellResistanceCheck(Context(owner,spell),other);first.CallComponents<PsychicSpiritMagicBonus>(x=>x.OnEventAboutToTrigger(pen));second.CallComponents<PsychicSpiritMagicBonus>(x=>x.OnEventAboutToTrigger(pen));Check(Bonus(pen,"m_AdditionalSpellPenetration")==2,"Font penetration2 once, not CL");}
 known.Clear();using(rt.RequestEventContext())Check(!(bool)AccessTools.Method(comp.GetType(),"Matches").Invoke(comp,new object[]{spell}),"Removed spirit immediately removes eligibility");}
 }
 }
 Clear();
 }
 static void Domains(BlueprintsCache c){Clear();var bp=Asset<BlueprintBuff>(c,"SpiritCallEffect");var comp=bp.GetComponent<PsychicSpiritMagicBonus>();var special=new AddSpecialSpellList();Set(special,"m_CharacterClass",comp.Druid);Set(special,"m_SpellList",comp.Spirits[0].List);var domain=Empty<Buff>();Set(domain,"<Blueprint>k__BackingField",new BlueprintBuff {ComponentsArray=new BlueprintComponent[]{special}});caster.Facts.List.Add(domain);var cls=new ClassData(comp.Druid.Get());Set(caster.Progression,"Classes",new List<ClassData>{cls});var spell=Unrelated();spell.AssetGuid=((List<BlueprintAbilityReference>)Get(comp.Spirits[0].List.Get().SpellsByLevel.First(x=>((List<BlueprintAbilityReference>)Get(x,"m_Spells")).Count>0),"m_Spells"))[0].Guid;var fact=Fact(bp,caster,"domain");foreach(int level in new[]{0,1,20}){cls.Level=level;using(fact.Components.Single().RequestEventContext())Check((bool)AccessTools.Method(comp.GetType(),"Matches").Invoke(comp,new object[]{spell})==(level>0),"Druid domain requires actual druid class level");}caster.Facts.List.Clear();Clear();}
 static void Stasis(BlueprintsCache c){var a=Asset<BlueprintAbility>(c,"TemporalStasis");var touch=a.GetComponent<AbilityEffectStickyTouch>().TouchDeliveryAbility;var bp=Asset<BlueprintBuff>(c,"TemporalStasisBuff");var comp=bp.GetComponent<PsychicStasisPause>();Check(touch.GetComponent<AbilityDeliverTouch>()!=null&&a.SpellResistance&&touch.SpellResistance,"Native held touch and SR");Check(!bp.GetComponents<AddCondition>().Any(x=>x.Condition==UnitCondition.Paralyzed)&&bp.GetComponents<AddCondition>().Any(x=>x.Condition==UnitCondition.CantAct),"Stasis not incorrectly blocked by paralysis immunity");
 foreach(int elapsed in new[]{0,6,30,60}){Clear();now=100;var ordinary=new BlueprintBuff {ComponentsArray=Array.Empty<BlueprintComponent>()};var timed=Fact(ordinary,owner,"timed");timed.EndTime=TimeSpan.FromSeconds(130);Set(timed,"<NextTickTime>k__BackingField",TimeSpan.FromSeconds(106));timed.NextResourceSpendingTime=TimeSpan.FromSeconds(112);var permanent=Fact(ordinary,owner,"permanent");permanent.EndTime=TimeSpan.MaxValue;Set(permanent,"<NextTickTime>k__BackingField",TimeSpan.MaxValue);var f=Fact(bp,caster,"stasis");f.EndTime=TimeSpan.FromSeconds(160);var rt=f.Components.Single();using(rt.RequestEventContext())AccessTools.Method(comp.GetType(),"OnTurnOn").Invoke(comp,null);Check(timed.EndTime==TimeSpan.FromSeconds(190)&&(TimeSpan)Get(timed,"<NextTickTime>k__BackingField")==TimeSpan.FromSeconds(166)&&timed.NextResourceSpendingTime==TimeSpan.FromSeconds(172),"End/tick/resource deadlines all paused");Check(permanent.EndTime==TimeSpan.MaxValue,"Permanent duration remains permanent");var state=rt.GetData<PsychicStasisPauseData>();var copy=Newtonsoft.Json.JsonConvert.DeserializeObject<PsychicStasisPauseData>(Newtonsoft.Json.JsonConvert.SerializeObject(state));Check(copy.Shifted&&copy.Amount==TimeSpan.FromSeconds(60)&&copy.BuffIds.SequenceEqual(new[]{"timed","permanent"}),"Save retains source IDs and original pause");Set(rt,"m_Data",copy);using(rt.RequestEventContext())AccessTools.Method(comp.GetType(),"OnTurnOn").Invoke(comp,null);Check(timed.EndTime==TimeSpan.FromSeconds(190),"Reload/activation does not shift twice");var newer=Fact(ordinary,owner,"later");newer.EndTime=TimeSpan.FromSeconds(200);now+=elapsed;using(rt.RequestEventContext())AccessTools.Method(comp.GetType(),"OnTurnOff").Invoke(comp,null);Check(timed.EndTime==TimeSpan.FromSeconds(130+elapsed)&&(TimeSpan)Get(timed,"<NextTickTime>k__BackingField")==TimeSpan.FromSeconds(106+elapsed)&&timed.NextResourceSpendingTime==TimeSpan.FromSeconds(112+elapsed),"Early or natural ending preserves only elapsed pause");Check(newer.EndTime==TimeSpan.FromSeconds(200)&&permanent.EndTime==TimeSpan.MaxValue,"Unrecorded/permanent effects untouched");using(rt.RequestEventContext())AccessTools.Method(comp.GetType(),"OnTurnOff").Invoke(comp,null);Check(timed.EndTime==TimeSpan.FromSeconds(130+elapsed),"Cleanup idempotent");
 foreach(var target in new[]{owner,other}){bool same=target==owner;using(rt.RequestEventContext()){var save=new RuleSavingThrow(target,SavingThrowType.Fortitude,99);comp.OnEventAboutToTrigger(save);Check(save.AutoPass==same,"Only suspended unit saves auto-pass");var damage=new RuleDealStatDamage(caster,target,StatType.Strength,new DiceFormula(1,DiceType.D4),0);comp.OnEventAboutToTrigger(damage);Check(damage.Immune==same,"Stat damage target routing");var drain=new RuleDrainEnergy(caster,target,EnergyDrainType.Permanent,null,new DiceFormula(1,DiceType.D4),0);comp.OnEventAboutToTrigger(drain);Check(drain.TargetIsImmune==same,"Negative level target routing");var heal=new RuleHealDamage(caster,target,new DiceFormula(1,DiceType.D4),0);comp.OnEventAboutToTrigger(heal);Check(heal.Interrupted==same,"Healing target routing");}}
 }
